// Application-owned local handler for Prompt 164.
// s is the lesson state; p contains validated classroom controls.
switch (action.op) {
    case 'host.claim':
        r.queue ??= [{ id: 'job-1', status: 'queued' }];
        r.claim = r.queue.find((item: Data) => item.status === 'queued');
        if (r.claim) {
            r.claim.status = 'claimed';
            r.claim.worker = 'classroom-local';
            accept({ claim: r.claim });
        }
        else
            reject('No queued work.');
        break;
}
